 716	        self: *Surface,
 717	        clipboard_type: apprt.Clipboard,
 718	        state: apprt.ClipboardRequest,
 719	    ) !apprt.ClipboardReadResult {
 720	        // Kitty clipboard writes carry their own contents and read
 721	        // nothing from the clipboard, so they skip the read callback
 722	        // entirely: the request is completed immediately, and a
 723	        // completion that requires confirmation diverts into the
 724	        // apprt confirmation flow just like a read.
 725	        if (state == .kitty_write) {
 726	            // A write to a location the embedder can't serve is
 727	            // rejected before the transaction completes so the caller
 728	            // answers ENOSYS without a permission prompt, matching
 729	            // reads, where the embedder reports an unsupported
